/** One semantic color's full role set - mirrors ColorScheme's primary/onPrimary/primaryContainer/onPrimaryContainer shape. */
@Immutable
data class ColorFamily(
  val color: Color,
  val onColor: Color,
  val colorContainer: Color,
  val onColorContainer: Color
)

/** Extended (non-M3-standard) semantic colors this app defines, per light/dark x contrast-level combination. */
@Immutable
data class ExtendedColorScheme(
  val timerAmber: ColorFamily,
  val goodAttention: ColorFamily,
)

val extendedLight = ExtendedColorScheme(
  timerAmber = ColorFamily(timerAmberContainerLight, onTimerAmberContainerLight, timerAmberLight, onTimerAmberLight),
  goodAttention = ColorFamily(goodAttentionContainerLight, onGoodAttentionContainerLight, goodAttentionLight, onGoodAttentionLight),
)

// Same "vivid value landed in the container role, not the base role" pattern as primary/
// primaryContainer in Theme.kt - swapped so timerAmber/goodAttention read as vivid brand amber/
// green in dark mode instead of the generated pastel tones. Verified contrast against the dark
// surface: timerAmber 10:1, goodAttention 3.5:1 (both comfortably pass); the swapped-in onColor
// values (onTimerAmberContainerDark/onGoodAttentionContainerDark) still contrast fine against
// their new base: 4.5:1 and 4.7:1.
val extendedDark = ExtendedColorScheme(
  timerAmber = ColorFamily(timerAmberContainerDark, onTimerAmberContainerDark, timerAmberDark, onTimerAmberDark),
  goodAttention = ColorFamily(goodAttentionContainerDark, onGoodAttentionContainerDark, goodAttentionDark, onGoodAttentionDark),
)

